using DomainModel.Models; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DomainModel.Configurations; public class CityConfiguration:IEntityTypeConfiguration<City>{ public void Configure(EntityTypeBuilder<City>b){ b.HasKey(x=>x.CityID); b.Property(x=>x.CityName).HasMaxLength(100).IsRequired(); b.Property(x=>x.Slug).HasMaxLength(250); b.Property(x=>x.SeoTitle).HasMaxLength(200); b.Property(x=>x.SeoDescription).HasMaxLength(500); b.Property(x=>x.SeoKeywords).HasMaxLength(500); b.Property(x=>x.CanonicalUrl).HasMaxLength(500); b.Property(x=>x.OpenGraphImageUrl).HasMaxLength(500); b.HasIndex(x=>new{x.ProvinceID,x.CityName}).IsUnique(); b.HasIndex(x=>new{x.ProvinceID,x.Slug}).IsUnique().HasFilter("[Slug] IS NOT NULL"); b.HasOne(x=>x.Province).WithMany(x=>x.Cities).HasForeignKey(x=>x.ProvinceID).OnDelete(DeleteBehavior.Restrict); }}